#!/usr/bin/env python3

def generate_crc32_table():
    table = []
    for i in range(256):
        crc = i
        for _ in range(8):
            if crc & 1:
                crc = (crc >> 1) ^ 0xEDB88320
            else:
                crc >>= 1
        table.append(crc)
    return table

def write_cpp_file(filename="crc32_table.cpp"):
    table = generate_crc32_table()
    
    cpp_content = """/**
 * @file crc32_table.cpp
 * @brief Auto-generated CRC-32 lookup table (IEEE 802.3 polynomial)
 * @note Generated by Python script
 */

#include <stdint.h>

// 256-entry precomputed lookup table for fast CRC-32 calculation
extern const uint32_t CRC32_TABLE[256] = {
"""
    
    # Format table values into 8 columns of hex numbers
    for i in range(0, 256, 8):
        row = [f"0x{val:08X}U" for val in table[i:i+8]]
        cpp_content += "    " + ", ".join(row) + ",\n"
        
    cpp_content += """};\n"""
    
    with open(filename, "w") as f:
        f.write(cpp_content)
        
    print(f"Successfully generated {filename}")

if __name__ == "__main__":
    write_cpp_file()